Definition malloc_pre_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo size TSD CTX TH sb TOP BOT : Z) (T : list Z) (d : depot) : machine_state -> Prop :=
  fun ms' => exists (x3 x4 x5 x12 x13 x14 x15 x16 x17 : word) (jk : list byte) (rest : list word) m',
    ms' = MS (mkR (wz 0x5008c) (Z_to_bv 64 (bv_unsigned sp + -2144)) gp tp x3 x4 x5 sp (wz size) (wz AINST) (wz size) (wz 8)
                  (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz 1) (wz 1) x12 x13 (wz 0x0747e8) (wz 1)
                  (Z_to_bv 64 (bv_unsigned sp + -2128)) (Z_to_bv 64 (bv_unsigned sp + -81)) s6 s7 s8 s9 s10 s11 x14 x15 x16 x17)
             F (Z_to_bv 64 0x500bc) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (TH + 3168, TH + 3169)] m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ IENV tp TSD CTX TH sb TOP BOT m'
    /\ stk bsegs m' lo (bv_unsigned sp + -2144)
    /\ rw_cells bsegs m' (bv_unsigned sp + -2144) [C8 sp; C8 (wz 0x074854)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))]
    /\ u64arr bsegs m' (bv_unsigned sp + -2128 + 16) (map wz T ++ rest) /\ length rest = (255 - length T)%nat
    /\ rw_cells bsegs m' (bv_unsigned sp + -72) [C8 sp]
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 8 jk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m' (TH + 3168) [C1 (b8 0)]
    /\ DEPOT bsegs d m'
    /\ Forall (fun x => 0 <= x < 2^64) T /\ (1 <= length T <= 30)%nat.

